        put("whiterun_plains", F.PLAINS, 1);
        put("pine_forest", F.FOREST, 1, F.PINE, 1);
        put("snowy_pine_forest", F.FOREST, 1, F.PINE, 1, F.SNOWY, 1);
        put("falkreath_forest", F.FOREST, 1, F.PINE, 1);
        put("rift_autumn_forest", F.FOREST, 1);
        put("reach_crags", F.MOUNTAIN, 1, F.PLAINS, 0.5f);
        put("reach_valley", F.PLAINS, 1, F.FOREST, 0.3f);
        put("hjaalmarch_marsh", F.MARSH, 1);
        put("eastmarch_volcanic_tundra", F.PLAINS, 1, F.HOT_SPRING, 0.25f);
        put("eastmarch_hot_springs", F.HOT_SPRING, 1, F.PLAINS, 0.5f);
        put("pale_snowfield", F.SNOWY, 1, F.PLAINS, 0.5f);
        put("winterhold_glacier", F.GLACIER, 1, F.SNOWY, 1);
        put("throat_of_the_world", F.SNOWY, 1, F.MOUNTAIN, 1, F.GLACIER, 0.3f);
        put("snowy_slopes", F.SNOWY, 1, F.MOUNTAIN, 1);
        put("alpine_meadow", F.PLAINS, 1, F.MOUNTAIN, 0.5f);
        put("skyrim_highlands", F.PLAINS, 1, F.MOUNTAIN, 0.5f);
        put("skyrim_coast", F.BEACH, 1, F.PLAINS, 0.3f);
        put("frozen_shore", F.BEACH, 1, F.SNOWY, 1);
        put("skyrim_river", F.RIVER, 1);
        put("frozen_river", F.RIVER, 0.6f, F.SNOWY, 1);
        put("skyrim_lake", F.RIVER, 0.7f);
        // ---- Morrowind and Solstheim
        put("solstheim_ashlands", F.ASH, 1);
        put("solstheim_pine_forest", F.FOREST, 1, F.PINE, 1, F.SNOWY, 1);
        put("red_mountain", F.ASH, 1, F.VOLCANIC, 1, F.MOUNTAIN, 0.5f);
        put("vvardenfell_ashlands", F.ASH, 1);
        put("molag_amur", F.ASH, 1, F.VOLCANIC, 0.7f);
        put("stonefalls", F.ASH, 0.7f, F.VOLCANIC, 0.3f, F.DESERT, 0.2f);
        put("bitter_coast_swamp", F.SWAMP, 1);
        put("grazelands", F.SAVANNA, 0.7f, F.PLAINS, 0.5f);
        put("west_gash", F.PLAINS, 1, F.MOUNTAIN, 0.3f);
        put("ascadian_isles", F.FOREST, 0.6f, F.PLAINS, 0.6f);
        put("azuras_coast", F.PLAINS, 0.6f, F.BEACH, 0.4f);
        put("sheogorad", F.MUSHROOM, 0.6f, F.PLAINS, 0.5f, F.BEACH, 0.3f);
        put("telvanni_mushroom_forest", F.MUSHROOM, 1, F.FOREST, 0.4f);
        put("deshaan_plains", F.SAVANNA, 0.6f, F.PLAINS, 0.6f);
        put("ash_shore", F.BEACH, 1, F.ASH, 0.5f);
        // ---- Cyrodiil
        put("heartlands", F.PLAINS, 1, F.FOREST, 0.3f);
        put("great_forest", F.FOREST, 1);
        put("colovian_highlands", F.PLAINS, 1, F.MOUNTAIN, 0.2f);
        put("gold_coast", F.PLAINS, 1);
        put("west_weald_vineyards", F.PLAINS, 1);
        put("nibenay_valley", F.PLAINS, 0.7f, F.FOREST, 0.3f, F.MARSH, 0.2f);
        put("blackwood_swamp", F.SWAMP, 1);
        put("jerall_foothills", F.FOREST, 1, F.PINE, 1, F.MOUNTAIN, 0.4f);
        put("lake_rumare_shore", F.RIVER, 0.7f, F.PLAINS, 0.4f);
        put("cyrodiil_river", F.RIVER, 1);
        put("temperate_beach", F.BEACH, 1);
        // ---- Black Marsh
        put("black_marsh_swamp", F.SWAMP, 1);
        put("deep_mire", F.SWAMP, 1);
        put("hist_grove", F.SWAMP, 0.7f, F.JUNGLE, 0.5f);
        put("mangrove_delta", F.SWAMP, 1, F.BEACH, 0.3f);
        put("shadowfen", F.SWAMP, 1);
