        put("valenwood_rainforest", F.JUNGLE, 1);
        put("graht_oak_forest", F.JUNGLE, 0.6f, F.FOREST, 0.6f);
        put("valenwood_mangrove_coast", F.SWAMP, 0.8f, F.JUNGLE, 0.3f, F.BEACH, 0.3f);
        put("reapers_march", F.FOREST, 1);
        put("jungle_river", F.RIVER, 1, F.JUNGLE, 0.5f);
