        // ---- Summerset
        put("summerset_meadow", F.PLAINS, 1);
        put("auridon_vineyards", F.PLAINS, 1);
        put("artaeum", F.PLAINS, 0.6f, F.FOREST, 0.4f, F.CRYSTAL, 0.3f);
        put("summerset_shore", F.BEACH, 1);
        put("crystal_coast", F.CRYSTAL, 1, F.BEACH, 0.5f);
        put("crystal_spires", F.CRYSTAL, 1, F.MOUNTAIN, 0.5f);
        // ---- Hammerfell
        put("alikr_dunes", F.DESERT, 1);
        put("alikr_desert", F.DESERT, 1);
